-- supabase/seed/0001_catalog.sql — MAGO catalog seed (spec §9). Idempotent: safe to re-run.
-- Images point at files generated by `npm run images` under public/.

begin;

-- ---------------------------------------------------------------------------
-- Settings
-- ---------------------------------------------------------------------------
insert into public.settings (id, store_name, currency, shipping_flat_fee, free_shipping_threshold, delivery_areas, social_links, announcement_bar)
values (
  true, 'MAGO', 'USD', 3.00, 30.00,
  '["Beirut","Mount Lebanon","North","Akkar","Beqaa","Baalbek-Hermel","South","Nabatieh"]'::jsonb,
  '{}'::jsonb,
  'Free delivery on orders over $30'
)
on conflict (id) do update set
  store_name = excluded.store_name,
  currency = excluded.currency,
  shipping_flat_fee = excluded.shipping_flat_fee,
  free_shipping_threshold = excluded.free_shipping_threshold,
  delivery_areas = excluded.delivery_areas,
  announcement_bar = excluded.announcement_bar;

-- ---------------------------------------------------------------------------
-- Collections
-- ---------------------------------------------------------------------------
insert into public.collections (slug, title, description, sort_order, is_visible) values
  ('fusilli', 'Fusilli', 'Twirly spirals that hold every drop of sauce.', 1, true),
  ('rishta', 'Rishta', 'Hearty Lebanese lentil and pasta comfort.', 2, true),
  ('pastina', 'Pastina', 'Tiny pasta, big comfort.', 3, true),
  ('tagliolini', 'Tagliolini', 'Silky ribbons with creamy, zesty sauces.', 4, true),
  ('conchiglie', 'Conchiglie', 'Little shells, rich and cheesy.', 5, true),
  ('specialities', 'Specialities', 'Signature recipes from our Mediterranean kitchen.', 6, true),
  ('best-sellers', 'Best Sellers', 'Our most-loved cups.', 7, false),
  ('pasta-boxes', 'Pasta Boxes 400g', 'Our pasta, ready for your own kitchen.', 8, true)
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  sort_order = excluded.sort_order,
  is_visible = excluded.is_visible;

-- ---------------------------------------------------------------------------
-- Cups (12) — $4.50, 30 g protein, ready in 3–4 minutes
-- ---------------------------------------------------------------------------
with shared as (
  select
    '[{"label":"Protein","value":"30 g per serving"},{"label":"Pasta","value":"100 g per cup"}]'::jsonb as nutrition,
    '[{"title":"Add water","body":"Pour hot water up to the fill line."},{"title":"Add sauce","body":"Stir in the sauce sachet."},{"title":"Mix & enjoy","body":"Wait 3–4 minutes, stir and enjoy."}]'::jsonb as preparation
)
insert into public.products (
  slug, name, flavour, sauce, type, tagline, short_description, description, story,
  price, status, sku, stock, track_inventory, protein_g, prep_minutes,
  is_best_seller, is_featured, sort_order, ingredients, nutrition, preparation,
  flavour_profiles, spice_level, textures, occasions, style, seo_description
)
select
  v.slug, v.name, v.flavour, v.sauce, 'cup', v.tagline, v.short_description, v.description, v.story,
  4.50, 'active', v.sku, 200, true, 30, 4,
  v.best_seller, v.featured, v.sort_order, v.ingredients::jsonb, shared.nutrition, shared.preparation,
  v.profiles::text[], v.spice, v.textures::text[], v.occasions::text[], v.style, v.short_description
from shared
cross join (values
  ('fusilli-spicy-muhammara', 'Fusilli Cup', 'Spicy Muhammara', 'Smoky pepper, walnut & chili sauce',
   'Bold. Smoky. Unforgettable.',
