  ('conchiglie', 'conchiglie-mac-and-cheese', 1),
  ('specialities', 'macaroon-bil-toum', 1), ('specialities', 'conchigliette-in-brodo', 2),
  ('specialities', 'lasagna-melanzane-ricotta', 3),
  ('best-sellers', 'fusilli-spicy-muhammara', 1),
  ('pasta-boxes', 'fusilli-400g', 1), ('pasta-boxes', 'tagliolini-400g', 2),
  ('pasta-boxes', 'conchiglie-400g', 3), ('pasta-boxes', 'lasagna-400g', 4)
) as v (collection_slug, product_slug, position)
join public.collections c on c.slug = v.collection_slug
