insert into public.discounts (title, kind, value, applies_to, min_cup_quantity, is_automatic, is_active)
select 'Mix & Match 10%', 'percentage', 10, 'cups', 5, true, true
where not exists (select 1 from public.discounts where title = 'Mix & Match 10%');

