-- ---------------------------------------------------------------------------
insert into public.recipes (
  slug, title, subtitle, hero_image, minutes, difficulty, servings, cups_used, is_vegetarian,
  tags, product_id, intro, ingredients, steps, tip, status, sort_order
)
