) as v (slug, title, subtitle, hero_image, minutes, veg, tags, product_slug, sort_order, intro, ingredients, steps, tip)
left join public.products p on p.slug = v.product_slug
on conflict (slug) do update set
  title = excluded.title, subtitle = excluded.subtitle, hero_image = excluded.hero_image,
  minutes = excluded.minutes, is_vegetarian = excluded.is_vegetarian, tags = excluded.tags,
  product_id = excluded.product_id, intro = excluded.intro, ingredients = excluded.ingredients,
  steps = excluded.steps, tip = excluded.tip, status = excluded.status, sort_order = excluded.sort_order;

