-- ---------------------------------------------------------------------------
insert into public.stores (slug, name, chain, type, address, area, city, lat, lng, hours) values
  ('spinneys-hamra', 'Spinneys Hamra', 'Spinneys', 'supermarket', 'Hamra Street', 'Hamra', 'Beirut', 33.8966, 35.4823, '{"summary":"Open until 10:00 PM"}'),
  ('carrefour-city-centre', 'Carrefour City Centre', 'Carrefour', 'supermarket', 'City Centre', 'Dbayeh', 'Dbayeh', 33.9380, 35.5880, '{"summary":"Open until 10:00 PM"}'),
  ('fahed-supermarket-achrafieh', 'Fahed Supermarket', 'Fahed', 'supermarket', 'Achrafieh', 'Achrafieh', 'Beirut', 33.8880, 35.5200, '{"summary":"Open until 9:00 PM"}'),
  ('metro-market-hazmieh', 'Metro Market', 'Metro Market', 'supermarket', 'Hazmieh', 'Hazmieh', 'Hazmieh', 33.8570, 35.5380, '{"summary":"Open until 10:00 PM"}'),
  ('azzi-supermarket-jal-el-dib', 'Azzi Supermarket', 'Azzi', 'supermarket', 'Jal el Dib', 'Jal el Dib', 'Jal el Dib', 33.9100, 35.5780, '{"summary":"Open until 9:00 PM"}')
on conflict (slug) do update set
  name = excluded.name, chain = excluded.chain, type = excluded.type, address = excluded.address,
  area = excluded.area, city = excluded.city, lat = excluded.lat, lng = excluded.lng, hours = excluded.hours;

insert into public.store_products (store_id, product_id)
select s.id, p.id
from public.stores s
cross join public.products p
where s.slug in ('spinneys-hamra', 'carrefour-city-centre', 'fahed-supermarket-achrafieh', 'metro-market-hazmieh', 'azzi-supermarket-jal-el-dib')
  and p.slug in ('fusilli-spicy-muhammara', 'fusilli-al-pesto-genovese', 'rishta-lentil-pasta-soup',
                 'pastina-sweet-cinnamon', 'tagliolini-al-tartufo-bianco', 'conchiglie-mac-and-cheese')
on conflict do nothing;

commit;
